'use strict';
const icons={box:'<rect x="4" y="5" width="16" height="14" rx="2"/><path d="M4 10h16"/>',key:'<circle cx="8" cy="9" r="4"/><path d="m11 12 8 8m-4-4 3-3m-1 5 3-3"/>',check:'<path d="m5 12 4 4L19 6"/>',bulb:'<path d="M9 18h6m-6 3h6M8 14a7 7 0 1 1 8 0l-1 2H9z"/>',book:'<path d="M12 5v15M3 4h5a4 4 0 0 1 4 2 4 4 0 0 1 4-2h5v15h-5a4 4 0 0 0-4 1 4 4 0 0 0-4-1H3z"/>',link:'<rect x="2" y="3" width="7" height="6" rx="1"/><rect x="15" y="15" width="7" height="6" rx="1"/><path d="M6 9v9h9"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>'};
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.box}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORE=window.TRACCIA_STORE || (window.TRACCIA_GAME?'traccia-er-v2-learning':'traccia-er-v1');let storageOK=true;
let saved;try{saved=JSON.parse(localStorage.getItem(STORE)||'null');}catch{saved=null;storageOK=false;}
let current=cases.some(c=>c.id===saved?.current)?saved.current:cases[0].id;
let states={};for(const c of cases){const raw=saved?.states?.[c.id];const s=ER.empty(c);if(raw&&typeof raw==='object'){
 s.entities=(Array.isArray(raw.entities)?raw.entities:[]).filter(id=>[...c.entities,...c.distractors].some(e=>e.id===id));
 for(const e of c.entities){s.attrs[e.id]=(Array.isArray(raw.attrs?.[e.id])?raw.attrs[e.id]:[]).filter(a=>e.attrs.some(f=>f.id===a));s.keys[e.id]=(Array.isArray(raw.keys?.[e.id])?raw.keys[e.id]:[]).filter(k=>s.attrs[e.id].includes(k));}
 for(const r of c.relations){const v=raw.relations?.[r.id];if(v&&typeof v==='object')s.relations[r.id]={from:c.entities.some(e=>e.id===v.from)?v.from:'',to:c.entities.some(e=>e.id===v.to)?v.to:'',a:['0,1','1,1','0,N','1,N'].includes(v.a)?v.a:'',b:['0,1','1,1','0,N','1,N'].includes(v.b)?v.b:'',...ER.relationFields(v)};}
 ER.restoreAssociations(c,s,raw);
 ER.restoreIdentifications(c,s,raw);
 const allCols=[...new Set(c.tables.flatMap(t=>t.cols.map(x=>x.name)).concat(c.trapColumns))];for(const t of [...c.tables.map(t=>t.name),...c.extraTables]){if(raw.tables?.[t]&&typeof raw.tables[t]==='object'){s.tables[t]={};for(const name of allCols){const col=raw.tables[t][name];if(col&&typeof col==='object')s.tables[t][name]={pk:!!col.pk,fk:typeof col.fk==='string'?col.fk:'',required:!!col.required,unique:!!col.unique};}}}
 c.questions.forEach((q,i)=>{if(Number.isInteger(raw.quiz?.[i])&&raw.quiz[i]>=0&&raw.quiz[i]<q.answers.length)s.quiz[i]=raw.quiz[i];});
 s.assisted=(Array.isArray(raw.assisted)?raw.assisted:[]).filter(i=>Number.isInteger(i)&&i>=0&&i<5);s.hints={};for(let i=0;i<5;i++)s.hints[i]=Math.min(2,Math.max(0,Number(raw.hints?.[i])||0));
 for(let i=0;i<5;i++){if(Array.isArray(raw.passed)&&raw.passed.includes(i)&&ER.check(c,s,i).ok&&(i===0||s.passed.includes(i-1)))s.passed.push(i);else break;}s.step=Math.max(0,Math.min(s.passed.length,4,Number(raw.step)||0));s.completed=s.passed.length===5;
 }states[c.id]=s;}
let view='lab',feedback=null,showModel=false,modelMode='er',dialog=null,reviewing=false;
const stageNames=['Entità','Attributi','Associazioni','Relazioni','Prova'];
const stageTitles=['Quali sono le entità?','Dai proprietà e identità alle entità','Associa le entità','Costruisci il modello relazionale','Metti alla prova il modello'];
const instructions=['Tocca gli oggetti che hanno un’identità propria. Distingui entità, attributi e singoli esempi.','Seleziona gli attributi richiesti. Tocca PK per indicare la chiave, anche quando è solo una parte dell’identificatore completo.','Individua le associazioni nella traccia, poi completa le due regole di lettura per ciascuna.','Aggiungi le tabelle e le colonne. Indica PK, destinazione delle FK e vincoli necessari. I campi descrittivi non hanno vincoli di obbligatorietà richiesti.','Prova casi concreti: una struttura corretta deve conservare le regole del problema.'];
function save(){try{localStorage.setItem(STORE,JSON.stringify({version:1,current,states}));}catch{storageOK=false;}}
function invalidate(){const s=states[current];s.passed=s.passed.filter(n=>n<s.step);s.completed=false;feedback=null;}
function modelHTML(c,s){let content='';if(modelMode==='tables'){content=Object.entries(s.tables).map(([name,cols])=>`<div class="relation-scroll" tabindex="0" role="region" aria-label="Tabella ${esc(name)}"><table class="relational-table"><caption>${esc(name)}</caption><thead><tr>${Object.keys(cols).map(n=>`<th scope="col">${esc(n)}</th>`).join('')||'<th>Nessuna colonna</th>'}</tr></thead><tbody><tr>${Object.values(cols).map(col=>`<td><strong class="key">${[col.pk?'PK':'',col.fk?'FK':''].filter(Boolean).join(' · ')||'—'}</strong>${col.fk?`<small>riferisce<br>${esc(col.fk)}</small>`:''}${col.required&&!col.pk?'<small>NOT NULL</small>':''}${col.unique?'<small>UNIQUE</small>':''}</td>`).join('')||'<td>Aggiungi una colonna</td>'}</tr></tbody></table></div>`).join('');}else{
 content=ERGraph.render(c,s);}
 return `<section class="model-preview" aria-label="Anteprima del modello"><div class="model-top"><span>${icon('link',16)} Il tuo modello</span><small>Si aggiorna con te</small></div>${s.step>=3?`<div class="model-switch"><button data-action="model-mode" data-mode="er" aria-pressed="${modelMode==='er'}">E/R</button><button data-action="model-mode" data-mode="tables" aria-pressed="${modelMode==='tables'}">Relazionale</button></div>`:''}<div class="canvas ${modelMode==='er'?'graph-canvas':''}"><div class="nodes">${content||`<p class="empty-model">${icon('box',28)}<br>Il modello prende forma<br>con le tue scelte.</p>`}</div></div><div class="legend">${modelMode==='er'?'PK = attributo della chiave. Per un’entità debole la chiave completa include il padre. Cardinalità accanto alle entità. Linea continua = obbligatoria; tratteggiata = facoltativa; spazio vuoto = da scegliere. ▼ / ▲ = verso di lettura. Ogni entità compare una sola volta; un’associazione ricorsiva torna sulla stessa entità.':'Una relazione è una tabella. Le FK riferiscono le chiavi delle altre tabelle.'}</div></section><div class="rule-note">${icon('bulb')}<div><strong>Un passo di ragionamento</strong><br>${s.step<3?'Prova a leggere ogni scelta con le parole della traccia. Il disegno deve raccontare la stessa storia.':s.passed.includes(3)?esc(c.rule):'Controlla che le tabelle conservino le regole del tuo modello E/R.'}</div></div>`;
}
function stageHTML(c,s){switch(s.step){case 0:return `<div class="selection-grid">${[...c.entities,...c.distractors].map(e=>`<button class="entity-choice" data-action="entity" data-id="${e.id}" aria-pressed="${s.entities.includes(e.id)}"><span class="choice-icon">${icon('box',23)}<span class="check-circle" aria-hidden="true">${s.entities.includes(e.id)?'✓':''}</span></span><span>${esc(e.name)}</span></button>`).join('')}</div><div class="selection-foot"><span>${s.entities.length} ${s.entities.length===1?'elemento selezionato':'elementi selezionati'}</span><span>Puoi cambiare idea</span></div>`;
case 1:return c.entities.map(e=>`<section class="entity-editor"><header><h3>${esc(e.name)}</h3><span class="tag">Entità</span></header>${e.attrs.map(a=>`<div class="attribute-row"><label><input type="checkbox" data-action="attr" data-entity="${e.id}" data-id="${a.id}" ${(s.attrs[e.id]||[]).includes(a.id)?'checked':''}>${esc(a.label)}</label><button class="pk-toggle" data-action="pk" data-entity="${e.id}" data-id="${a.id}" aria-label="${esc(e.name+'.'+a.label)}: parte della chiave" aria-pressed="${(s.keys[e.id]||[]).includes(a.id)}" ${!(s.attrs[e.id]||[]).includes(a.id)?'disabled':''}>PK</button></div>`).join('')}${identificationHTML(c,s,e)}</section>`).join('');
case 2:return associationStageHTML(c,s);
case 3:return `<p class="small-note">Conversione guidata${c.type==='1:1'?': mantieni le due tabelle e colloca la FK in Tessere':'. Usa i nomi proposti'}. PK implica obbligatorietà. Per una PK composta è univoca la combinazione, non ogni colonna da sola.</p><div class="table-tray">${[...c.tables.map(t=>t.name),...c.extraTables].map(name=>`<button class="table-chip" data-action="table" data-name="${name}" aria-pressed="${!!s.tables[name]}">${s.tables[name]?'✓':'+'} ${esc(name)}</button>`).join('')}</div>${Object.entries(s.tables).map(([name,cols])=>`<section class="table-editor"><header><h3>${esc(name)}</h3><span class="mini-label">Relazione</span></header>${Object.entries(cols).map(([n,col])=>`<div class="column-item"><div class="column-head"><b>${esc(n)}</b><button class="remove" data-action="remove-col" data-table="${name}" data-col="${n}" aria-label="Rimuovi ${esc(name+'.'+n)}">×</button></div><div class="column-options">${[['pk','PK'],['required','Obbligatorio'],['unique','UNIQUE']].map(([key,label])=>`<label><input type="checkbox" aria-label="${esc(name+'.'+n+': '+label)}" data-action="col-flag" data-table="${name}" data-col="${n}" data-prop="${key}" ${col[key]||key==='required'&&col.pk?'checked':''} ${key==='required'&&col.pk?'disabled':''}>${label}</label>`).join('')}</div><label class="sr-only" for="fk-${name}-${n}">Chiave esterna di ${esc(name+'.'+n)}</label><select id="fk-${name}-${n}" data-action="col-fk" data-table="${name}" data-col="${n}"><option value="">Nessuna chiave esterna</option>${c.tables.flatMap(t=>t.cols.filter(x=>x.pk).map(x=>`${t.name}.${x.name}`)).map(target=>`<option value="${target}" ${col.fk===target?'selected':''}>FK: ${esc(target)}</option>`).join('')}</select></div>`).join('')}<label class="sr-only" for="add-${name}">Aggiungi colonna a ${esc(name)}</label><select class="field-select" id="add-${name}" data-action="add-col" data-table="${name}"><option value="">+ Aggiungi una colonna</option>${[...new Set(c.tables.flatMap(t=>t.cols.map(x=>x.name)).concat(c.trapColumns))].filter(n=>!cols[n]).map(n=>`<option value="${n}">${esc(n)}</option>`).join('')}</select><div class="schema-line">${esc(name)}(${Object.entries(cols).map(([n,col])=>`${esc(n)}${col.pk?' {PK}':''}${col.fk?' {FK}':''}`).join(', ')||'…'})</div></section>`).join('')}`;
case 4:return c.questions.map((q,i)=>`<section class="question"><h3>${i+1}. ${esc(q.q)}</h3>${q.answers.map((a,j)=>`<button class="answer" data-action="answer" data-q="${i}" data-answer="${j}" aria-pressed="${s.quiz[i]===j}"><span class="answer-num">${String.fromCharCode(65+j)}</span><span>${esc(a)}</span></button>`).join('')}</section>`).join('');}}
function identificationHTML(c,s,e){const v=s.identifications[e.id]||{};return `<div class="identification-editor"><label for="identity-${e.id}">Come si identifica ${esc(e.name)}?</label><select id="identity-${e.id}" data-action="identification" data-entity="${e.id}" data-prop="kind"><option value="">Scegli l’identificazione</option><option value="autonomous" ${v.kind==='autonomous'?'selected':''}>Con una chiave autonoma</option><option value="dependent" ${v.kind==='dependent'?'selected':''}>Dipende da un’altra entità</option></select>${v.kind==='dependent'?`<label for="owner-${e.id}">Quale entità contribuisce alla chiave completa?</label><select id="owner-${e.id}" data-action="identification" data-entity="${e.id}" data-prop="owner"><option value="">Scegli l’entità</option>${c.entities.filter(n=>n.id!==e.id).map(n=>`<option value="${n.id}" ${v.owner===n.id?'selected':''}>${esc(n.name)}</option>`).join('')}</select>`:''}</div>`;}
function associationStageHTML(c,s){
 if(!s.associationsConfirmed){const candidates=c.relations.flatMap((r,i)=>[r,...(c.associationDistractors[i]?[c.associationDistractors[i]]:[])]).concat(c.associationDistractors.slice(c.relations.length)).sort((a,b)=>a.verb.localeCompare(b.verb,'it'));return `<p class="association-progress">1 di 2 · Individua le associazioni</p><p class="small-note">Quali azioni collegano le entità nella traccia? Seleziona tutte e solo quelle presenti.</p><div class="selection-grid association-choices">${candidates.map(r=>`<button class="entity-choice" data-action="association-choice" data-id="${r.id}" aria-pressed="${s.associationChoices.includes(r.id)}"><span class="choice-icon">${icon('link')}<span class="check-circle" aria-hidden="true">${s.associationChoices.includes(r.id)?'✓':''}</span></span>${esc(r.verb)}</button>`).join('')}</div>`;}
 return `<div class="association-phase"><p class="association-progress">2 di 2 · Completa le regole di lettura</p><button class="text-button" data-action="association-back">Rivedi le associazioni scelte</button></div>`+c.relations.filter(r=>s.associationChoices.includes(r.id)).map(r=>{const v=s.relations[r.id]||{},f=ER.relationFields(v),entities=[c.entities.find(e=>e.id===v.from),c.entities.find(e=>e.id===v.to)],reverse=r.from!==r.to&&v.from===r.to&&v.to===r.from;const verbs=reverse?[r.reading[1],r.reading[0]]:r.reading;
 return `<section class="relation-editor"><h3>${esc(r.verb)} ${r.attr?`<span class="tag">Attributo: ${esc(r.attr)}</span>`:''}</h3><div class="form-grid">${['from','to'].map((k,i)=>`<div class="control"><label for="${r.id}-${k}">${r.from===r.to?(i?'Ruolo componente':'Ruolo composta'):(i?'Seconda entità':'Prima entità')}</label><select id="${r.id}-${k}" data-action="relation" data-id="${r.id}" data-prop="${k}"><option value="">Scegli l’entità</option>${c.entities.map(e=>`<option value="${e.id}" ${v[k]===e.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select></div>`).join('')}</div>${entities.every(Boolean)?`<div class="reading-rules">${[0,1].map(i=>{const side=i?'B':'A',subject=entities[i],target=entities[1-i],role=r.from===r.to?(i?' componente':' composta'):'';return `<fieldset class="reading-sentence"><legend>${i+1}. Da ${esc(subject.name+role)} a ${esc(target.name+(r.from===r.to?(i?' composta':' componente'):''))}</legend><div class="sentence-flow"><span>Ogni <strong>${esc(subject.name+role)}</strong></span><label class="sr-only" for="${r.id}-part${side}">Partecipazione di ${esc(subject.name+role)}</label><select id="${r.id}-part${side}" data-action="relation" data-id="${r.id}" data-prop="part${side}"><option value="">deve / può</option><option value="1" ${f['part'+side]==='1'?'selected':''}>deve</option><option value="0" ${f['part'+side]==='0'?'selected':''}>può</option></select><span>${esc(verbs[i])}</span><label class="sr-only" for="${r.id}-max${side}">Molteplicità massima da ${esc(subject.name+role)} a ${esc(target.name)}</label><select id="${r.id}-max${side}" data-action="relation" data-id="${r.id}" data-prop="max${side}"><option value="">quanti?</option><option value="1" ${f['max'+side]==='1'?'selected':''}>${esc(target.quantifiers[0])}</option><option value="N" ${f['max'+side]==='N'?'selected':''}>${esc(target.quantifiers[1])}</option></select></div></fieldset>`;}).join('')}</div><p class="small-note">“Può” ammette anche nessuna partecipazione. “Deve” ne richiede almeno una. Il secondo selettore indica il massimo.</p>`:'<p class="reading">Scegli le due entità per completare le frasi nei due versi.</p>'}</section>`;
 }).join('');
}
function hintFor(c,s){if(s.step===2&&!s.associationsConfirmed)return (s.hints[2]||0)>1?'Cerca i verbi che collegano gli oggetti nella traccia. Un’azione plausibile nel mondo reale non basta: deve essere richiesta dal problema.':'Rileggi chi fa che cosa. Non aggiungere operazioni di cui la traccia non parla.';const hints=[c.hints,c.attributeHints||['Seleziona nomi di proprietà, non esempi concreti. Un titolo può ripetersi.','I codici identificano gli oggetti. Nelle entità deboli la chiave locale si completa con quella del padre.'],['Leggi una frase alla volta, partendo da una singola istanza. “Può” ammette zero, “deve” richiede almeno uno.',c.relations.map(r=>r.why).join(' ')],['Prima crea una tabella per ogni entità. Poi valuta ogni associazione: FK sul lato N oppure tabella ponte per N:N.',c.relationalHint],['Prova i dati descritti nelle domande contro i minimi, i massimi e le chiavi che hai scelto.',c.rule]];return hints[s.step][Math.min(1,(s.hints[s.step]||1)-1)];}
function feedbackHTML(){return feedback?`<div class="feedback ${feedback.ok?'success':''}" id="feedback" role="status" tabindex="-1"><h3>${icon(feedback.ok?'check':'info')}${feedback.ok?'Ci sei. Il modello regge.':'C’è qualcosa da rivedere'}</h3>${feedback.ok?'<p>Hai rispettato i requisiti di questo passaggio. Puoi continuare.</p>':`<ul>${feedback.issues.slice(0,6).map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${feedback.issues.length>6?'<p class="small-note">Sistema questi punti, poi verifica di nuovo.</p>':''}`}</div>`:'';}
function render(){const c=cases.find(c=>c.id===current),s=states[current];document.title=`${view==='lab'?c.short:view==='path'?'Il percorso':'Ripasso'} · Traccia`;document.getElementById('app').innerHTML=`<header class="header"><button class="brand" data-action="view" data-view="path" aria-label="Traccia: apri il percorso"><span class="brandmark">${icon('link',23)}</span><span class="wordmark">traccia<small>laboratorio di basi di dati</small></span></button><span class="header-progress">${icon('book',17)}<strong>${cases.filter(c=>states[c.id].completed).length}/${cases.length}</strong> <span>completati</span></span></header><nav class="nav" aria-label="Navigazione principale">${[['lab','Laboratorio'],['path','Percorso'],['rules','Ripasso']].map(([id,name])=>`<button data-action="view" data-view="${id}" ${view===id?'aria-current="page"':''}>${name}</button>`).join('')}</nav>${!window.TRACCIA_GAME?'<a class="v2-link" href="v2/">Gioca a Traccia V2 · Archivio in ordine</a>':''}${!storageOK?'<div class="storage-warning">Il browser non consente il salvataggio. Puoi esercitarti, ma chiudendo la pagina perderai i progressi.</div>':''}<main class="shell" id="workspace" tabindex="-1">${view==='path'?pathHTML():view==='rules'?rulesHTML():s.completed&&!reviewing?completeHTML(c,s):labHTML(c,s)}</main>${view==='lab'&&(!s.completed||reviewing)?`<div class="footer-action"><div class="action-inner"><button class="back" data-action="previous" ${s.step===0?'disabled':''}>Indietro</button><span class="action-info">${stageNames[s.step]} · ${s.step+1} di 5</span><button class="primary" data-action="${s.passed.includes(s.step)?'next':'check'}">${s.passed.includes(s.step)?(s.step===4?'Concludi il laboratorio':'Continua'):'Verifica le scelte'}${icon(s.passed.includes(s.step)?'check':'link',19)}</button></div></div>`:''}${dialog?dialogHTML():''}`;}
function labHTML(c,s){return `<header class="lesson-head"><div class="eyebrow"><span class="dash"></span>Laboratorio ${String(cases.indexOf(c)+1).padStart(2,'0')} / ${String(cases.length).padStart(2,'0')}</div><h1>${esc(c.title)}</h1><div class="lesson-meta"><span class="tag">${c.type}</span><span>${c.level}</span><span>≈ ${c.minutes} min</span></div></header><div class="steps" aria-label="Passaggi del laboratorio">${stageNames.map((n,i)=>`<div class="step ${i===s.step?'active':''} ${s.passed.includes(i)?'done':''}"><button data-action="step" data-step="${i}" aria-label="${i+1}. ${n}" ${i>s.passed.length?'disabled':''} ${i===s.step?'aria-current="step"':''}>${s.passed.includes(i)?'✓':i+1}</button><span>${n}</span></div>`).join('')}</div><div class="work-layout"><section><div class="stage-heading"><div><h2>${stageTitles[s.step]}</h2><p class="instruction">${instructions[s.step]}</p></div></div><details class="brief" ${s.step===0?'open':''}><summary><span class="prompt-label">${icon('book',18)} La traccia</span></summary><p class="brief-body">${esc(c.prompt)}</p></details>${stageHTML(c,s)}${feedbackHTML()}<div class="help-row"><button class="text-button" data-action="hint">${icon('bulb',18)} ${s.hints[s.step]?'Un altro indizio':'Dammi un indizio'}</button>${s.hints[s.step]>=2?'<button class="text-button" data-action="solve">Mostra questo passaggio</button>':''}</div>${s.hints[s.step]?`<div class="tip" role="status">${esc(hintFor(c,s))}</div>`:''}${s.assisted.includes(s.step)?'<p class="small-note">Passaggio svolto con la soluzione. Potrai rifarlo senza aiuti.</p>':''}<button class="mobile-model-button" data-action="model-toggle" aria-expanded="${showModel}">${icon('link',19)} ${showModel?'Nascondi':'Guarda'} il tuo modello</button></section><aside class="aside ${!showModel?'mobile-hidden':''}" id="model-panel">${modelHTML(c,s)}</aside></div>`;}
function pathHTML(){return `<div class="view-title"><div class="eyebrow"><span class="dash"></span>Impara costruendo</div><h1>Una traccia alla volta.</h1><p>Parti dalle entità. Costruisci i legami. Trasforma il modello in tabelle. Scegli un laboratorio e riprendi da dove eri rimasto.</p></div><div class="course-grid">${cases.map((c,i)=>{const s=states[c.id];return `<article class="course ${c.id===current?'active':''}"><div class="course-head"><span class="course-index">${String(i+1).padStart(2,'0')} / LAB</span><span class="tag">${c.type}</span></div><h2>${esc(c.title)}</h2><p>${esc(c.intro)}</p><div class="course-bottom"><span>${s.completed?(s.assisted.length?'Svolto con aiuti':'Completato'):s.passed.length?`${s.passed.length}/5 passaggi`:'≈ '+c.minutes+' min'}</span><button data-action="case" data-id="${c.id}">${s.completed?'Rivedi':s.passed.length?'Riprendi':'Apri laboratorio'}</button></div><div class="course-bars" aria-hidden="true">${stageNames.map((_,i)=>`<i class="${s.passed.includes(i)?'filled':''}"></i>`).join('')}</div></article>`;}).join('')}</div><p class="local-note">I progressi restano solo in questo browser. Nessun account necessario nella versione locale. Gli esercizi seguono le ipotesi dichiarate: in altri contesti possono esistere modelli diversi.</p>`;}
function rulesHTML(){const rules=[['Entità, attributo, istanza','Un’entità descrive un tipo di oggetti. L’attributo è una proprietà; l’istanza è un oggetto concreto.','Libro: entità\nTitolo: attributo\nL01, “Il viaggio”: valori di un’istanza'],['Associazione e relazione','Nell’E/R un’associazione lega entità. Nel modello relazionale una relazione è un insieme di tuple, rappresentato da una tabella.','Appartenere: associazione\nLibri(CodLibro, Titolo, CodCategoria): relazione'],['Chiavi e unicità','La PK identifica una riga e non ammette NULL. Se è composta, è l’intera combinazione a dover essere unica. Nome e titolo non garantiscono l’unicità.','PK = (CodOrdine, NumeroRiga)\n(O1, 1) e (O2, 1) sono distinti'],['Cardinalità e partecipazione','Prima scegli la cardinalità: 1:1, 1:N, N:1 oppure N:N, nell’ordine delle entità. Poi scegli separatamente se ciascuna entità partecipa in modo obbligatorio o facoltativo.','Libro : Categoria = N:1\nLibro: obbligatoria · Categoria: facoltativa'],['Conversione 1:N','Crea una tabella per ogni entità. Copia la PK del lato 1 nella tabella del lato N come FK. Anche gli attributi dell’associazione vanno sul lato N.','Libri(..., CodCategoria {FK})\nCodCategoria riferisce Categorie.CodCategoria'],['Conversione 1:1','Una FK UNIQUE conserva il massimo 1. Preferisci inserirla sul lato con partecipazione obbligatoria. Se entrambi i lati sono obbligatori, è possibile anche una fusione.','Tessere(..., CodSocio {FK})\nCodSocio: NOT NULL e UNIQUE'],['Conversione N:N','Aggiungi una tabella ponte. Le due FK formano di solito la PK composta, se ogni coppia compare una sola volta. Gli attributi dell’associazione vanno nella tabella ponte.','Partecipazioni(CodArtista {PK,FK},\nCodBrano {PK,FK}, Ruolo)'],['Entità deboli','La chiave locale si combina con quella del padre. Segniamo {PK} anche sulla parte locale. Una semplice partecipazione obbligatoria, da sola, non rende debole un’entità.','RigheOrdine(CodOrdine {PK,FK},\nNumeroRiga {PK}, Quantità)'],['Ricorsione','La stessa entità partecipa in ruoli diversi. In N:N, la tabella ponte ha due FK verso la stessa tabella. Distingui i nomi dei ruoli.','Composizioni(CodComposta {PK,FK},\nCodComponente {PK,FK})'],['I vincoli che restano','Le FK verificano i riferimenti. Non garantiscono ogni minimo sul padre né l’assenza di cicli. Questi vincoli richiedono controlli aggiuntivi.','Ogni articolo ha almeno un autore:\nla sola FK della tabella ponte non basta.']];return `<div class="view-title"><div class="eyebrow"><span class="dash"></span>Da tenere a portata di mano</div><h1>Le regole, con un esempio.</h1><p>Un riferimento breve da consultare mentre costruisci il tuo modello.</p></div><div class="rule-list">${rules.map(([title,body,ex])=>`<article class="rule-card"><h2>${title}</h2><p>${body}</p><div class="example">${esc(ex).replaceAll('\n','<br>')}</div></article>`).join('')}</div>`;}
function completeHTML(c,s){const next=cases[cases.indexOf(c)+1];return `<section class="completion"><div class="seal">${icon('check',35)}</div><div class="eyebrow" style="justify-content:center">Laboratorio completato</div><h1>${esc(c.title)}</h1><p>Hai riconosciuto le entità, costruito le associazioni e convertito il modello in relazioni.</p><div class="rule-summary"><div class="mini-label">La regola da ricordare</div><p>${esc(c.rule)}</p>${s.assisted.length?`<span class="small-note">${s.assisted.length} passaggi svolti con la soluzione. Ripetili per verificare se sai procedere da solo.</span>`:'<span class="small-note">Tutti i passaggi completati senza mostrare la soluzione.</span>'}</div>${next?`<button class="primary" data-action="case" data-id="${next.id}">Prossimo: ${esc(next.short)}</button>`:'<button class="primary" data-action="view" data-view="path">Torna al percorso</button>'}<button class="secondary" data-action="review">Rivedi il tuo modello</button><button class="text-button" data-action="reset">Rifai questo laboratorio</button></section>`;}
function dialogHTML(){return `<div class="dialog-backdrop"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">Ricominciare questo laboratorio?</h2><p>Le risposte di questo esercizio verranno azzerate. Gli altri laboratori manterranno i loro progressi.</p><div class="dialog-actions"><button class="secondary" data-action="cancel-reset" autofocus>Annulla</button><button class="primary" data-action="confirm-reset">Ricomincia</button></div></section></div>`;}
function goTop(){window.scrollTo({top:0,behavior:'instant'});document.getElementById('workspace')?.focus({preventScroll:true});}
function eventHandler(event){const el=event.target.closest('[data-action]');if(!el)return;let a=el.dataset.action;if(a==='check'&&states[current].step===2&&!states[current].associationsConfirmed)a='check-associations';const inputActions=['identification','attr','relation','add-col','col-flag','col-fk'];if(event.type==='click'&&inputActions.includes(a)||event.type==='change'&&!inputActions.includes(a))return;
 const c=cases.find(c=>c.id===current),s=states[current];let top=false,focusFeedback=false;const id=el.id;
 window.Game?.beforeAction(a,c,s,el);
 if(['identification','association-choice','entity','attr','pk','relation','table','remove-col','add-col','col-flag','col-fk','answer'].includes(a))invalidate();
 switch(a){case 'association-choice':{const id=el.dataset.id;s.associationChoices=s.associationChoices.includes(id)?s.associationChoices.filter(x=>x!==id):[...s.associationChoices,id];s.associationsConfirmed=false;break;}
 case 'check-associations':feedback=ER.checkAssociations(c,s);if(feedback.ok){s.associationsConfirmed=true;feedback=null;top=true;}else focusFeedback=true;break;
 case 'association-back':s.associationsConfirmed=false;feedback=null;top=true;break;
 case 'view':reviewing=false;view=el.dataset.view;feedback=null;top=true;break;
 case 'case':reviewing=false;current=el.dataset.id;view='lab';feedback=null;showModel=false;modelMode='er';top=true;break;
 case 'entity':{const x=el.dataset.id;s.entities=s.entities.includes(x)?s.entities.filter(v=>v!==x):[...s.entities,x];break;}
 case 'attr':{const e=el.dataset.entity,x=el.dataset.id;const v=s.attrs[e]||[];s.attrs[e]=el.checked?[...v,x]:v.filter(a=>a!==x);if(!el.checked)s.keys[e]=(s.keys[e]||[]).filter(a=>a!==x);break;}
 case 'identification':{const v=s.identifications[el.dataset.entity]||={kind:'',owner:''};v[el.dataset.prop]=el.value;if(el.dataset.prop==='kind')v.owner='';break;}
 case 'pk':{const e=el.dataset.entity,x=el.dataset.id,v=s.keys[e]||[];s.keys[e]=v.includes(x)?v.filter(a=>a!==x):[...v,x];break;}
 case 'relation':s.relations[el.dataset.id]||={};ER.setRelation(s.relations[el.dataset.id],el.dataset.prop,el.value);break;
 case 'table':{const name=el.dataset.name;if(s.tables[name])delete s.tables[name];else s.tables[name]={};break;}
 case 'add-col':if(el.value)s.tables[el.dataset.table][el.value]={pk:false,fk:'',required:false,unique:false};break;
 case 'remove-col':delete s.tables[el.dataset.table][el.dataset.col];break;
 case 'col-flag':s.tables[el.dataset.table][el.dataset.col][el.dataset.prop]=el.checked;break;
 case 'col-fk':s.tables[el.dataset.table][el.dataset.col].fk=el.value;break;
 case 'answer':s.quiz[el.dataset.q]=Number(el.dataset.answer);break;
 case 'check':feedback=ER.check(c,s,s.step);if(feedback.ok&&!s.passed.includes(s.step))s.passed.push(s.step);focusFeedback=true;break;
 case 'next':if(s.passed.includes(s.step)){if(s.step===4){s.completed=true;reviewing=false;}else s.step++;feedback=null;top=true;}break;
 case 'previous':if(s.step>0){s.step--;feedback=null;top=true;}break;
 case 'step':if(Number(el.dataset.step)<=s.passed.length){s.step=Number(el.dataset.step);feedback=null;top=true;}break;
 case 'hint':s.hints[s.step]=Math.min(2,(s.hints[s.step]||0)+1);break;
 case 'solve':ER.solve(c,s,s.step);if(!s.assisted.includes(s.step))s.assisted.push(s.step);feedback=null;break;
 case 'model-toggle':showModel=!showModel;break;
 case 'model-mode':modelMode=el.dataset.mode;break;
 case 'review':reviewing=true;s.step=3;feedback=null;showModel=true;modelMode='tables';top=true;break;
 case 'reset':dialog=true;break;
 case 'cancel-reset':dialog=null;break;
 case 'confirm-reset':states[current]=ER.empty(c);dialog=null;feedback=null;showModel=false;top=true;break;
 }
 window.Game?.afterAction(a,c,s,el);save();render();if(top)goTop();else if(focusFeedback)document.getElementById('feedback')?.focus();else if(id)document.getElementById(id)?.focus({preventScroll:true});else {const match=[...document.querySelectorAll('[data-action]')].find(x=>x.dataset.action===a&&Object.entries(el.dataset).every(([k,v])=>x.dataset[k]===v));match?.focus({preventScroll:true});}if(a==='model-toggle'&&showModel)document.getElementById('model-panel')?.scrollIntoView({behavior:'smooth',block:'start'});if(dialog)document.querySelector('[data-action="cancel-reset"]')?.focus();}
document.addEventListener('click',eventHandler);document.addEventListener('change',eventHandler);document.addEventListener('keydown',e=>{if(!dialog)return;if(e.key==='Escape'){dialog=null;render();}if(e.key==='Tab'){const buttons=[...document.querySelectorAll('.dialog button')];if(e.shiftKey&&document.activeElement===buttons[0]){e.preventDefault();buttons.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===buttons.at(-1)){e.preventDefault();buttons[0].focus();}}});
if(!window.TRACCIA_GAME)render();
